<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Subscription extends Model { protected $fillable=['subscriber_id','creator_id','provider','provider_reference','amount','status','starts_at','ends_at']; protected function casts(): array { return ['amount'=>'decimal:2','starts_at'=>'datetime','ends_at'=>'datetime']; } public function isActive(): bool { return $this->status === 'active' && (!$this->ends_at || $this->ends_at->isFuture()); } }
